-- china_address_dict 全量初始化（全国区县，数据源 DataV 行政区划）
-- 可重复执行：按 adcode 唯一键 upsert
ON DUPLICATE KEY UPDATE prov=VALUES(prov), city=VALUES(city), area=VALUES(area), full_name=VALUES(full_name), division_id=VALUES(division_id), gps=VALUES(gps), gps_center=VALUES(gps_center), poi_id=VALUES(poi_id), poi_name=VALUES(poi_name), detail=VALUES(detail), sync_status='success';
